**Issue:** Lazy singleton initialization without synchronization.
**Why:** Two threads can both see _instance is None and create two instances, breaking the singleton contract.
**Fix:**
import threading

class Config:
    _instance = None
    _lock = threading.Lock()
    @classmethod
    def get(cls):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = Config()
        return cls._instance

